{% set group = attribute(site, 'club-einstellungen') %}
{% set team_slug = 'erste' %} {# anpassen: erste/zweite/dritte/jugend/ah #}
{% set start_offset = 0 %}
{% set limit = 3 %}

{% set all_matches = attribute(group, 'spieltage_teams') %}

{% set matches = all_matches|length >= 1
  ? all_matches
    |filter(v => (attribute(v, 'team').value|default(attribute(v, 'team'))) == team_slug)
    |filter(v => attribute(v, 'date_nextmatch').timestamp > mb.microtime(true))
    |sort((a, b) => attribute(a, 'date_nextmatch').timestamp <=> attribute(b, 'date_nextmatch').timestamp)
  : []
%}

<ul class="club-match-list">
  {% for clone in matches|slice(start_offset, limit) %}
    {% set home = attribute(clone, 'heimmannschaft') %}
    {% set away = attribute(clone, 'auswaerts') %}
    <li class="club-table">
      <p>{{ clone.liga }} // {{ clone.date_nextmatch.timestamp|date("d.m.Y") }} um {{ clone.date_nextmatch.timestamp|date("H:i") }} Uhr</p>
      <div class="club-next-match">
        <div class="club-team-block">
          <p class="club-team-name">{{ home.title }}</p>
          <img src="{{ home.thumbnail.medium_large.url }}" alt="{{ home.thumbnail.medium_large.alt }}">
        </div>
        <span class="club-vs-nextgame">
          {% if clone.abgesagt == 1 %}<p class="club-canceled">Abgesagt</p>{% else %}<p class="club-vs">vs</p>{% endif %}
        </span>
        <div class="club-team-block">
          <p class="club-team-name">{{ away.title }}</p>
          <img src="{{ away.thumbnail.medium_large.url }}" alt="{{ away.thumbnail.medium_large.alt }}">
        </div>
      </div>
    </li>
  {% endfor %}
</ul>
